        "quote": "不要硬扶着走，立刻打120"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00017",
        "explanation": "医生正确整合化疗后状态与呼吸、感染表现，并排除普通感冒式观察路径。",
        "quote": "不能当成普通的感冒再观察"
      }
    ],
    "continuity_memory_focus": [
